import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

listener_return = verify('listener_return', '''
    use core.http;
    fn open_listener() -> HttpHandle {
        return http.bind("127.0.0.1:8787")
    }
    fn main() -> i32 {
        let listener = open_listener()
        close(listener)
        return 0
    }
''', 0)
assert listener_return['errors'] == 0, listener_return
assert not any('potential resource escape' in message for message in messages(listener_return)), listener_return

process_return = verify('process_return', '''
    use core.proc;
    fn start() -> ProcessHandle {
        let argv = proc.argv_new()
        let env = proc.env_new()
        return proc.spawn_cmd("echo", argv, env, "")
    }
    fn main() -> i32 {
        let handle = start()
        discard proc.close(handle)
        return 0
    }
''', 0)
assert process_return['errors'] == 0, process_return
assert not any('potential resource escape' in message for message in messages(process_return)), process_return
assert not any('linear value `argv` was not consumed/freed' in message for message in messages(process_return)), process_return
assert not any('linear value `env` was not consumed/freed' in message for message in messages(process_return)), process_return

stream_return = verify('stream_return', '''
    use core.http;
    fn open_stream() -> HttpStreamHandle {
        return http.post_json_stream("https://example.com", "{}")
    }
    fn main() -> i32 {
        let stream = open_stream()
        discard http.stream_close(stream)
        return 0
    }
''', 0)
assert stream_return['errors'] == 0, stream_return
assert not any('potential resource escape' in message for message in messages(stream_return)), stream_return

task_group_return = verify('task_group_return', '''
    use core.thread;
    fn start_group() -> TaskGroupHandle {
        return task.group_begin()
    }
    fn main() -> i32 {
        let group = start_group()
        discard task.group_cancel(group)
        return 0
    }
''', 0)
assert task_group_return['errors'] == 0, task_group_return
assert not any('potential resource escape' in message for message in messages(task_group_return)), task_group_return

websocket_return = verify('websocket_return', '''
    use core.http;
    fn accept_ws(conn: HttpHandle) -> WebSocketHandle {
        return http.websocket_accept(conn)
    }
    fn main() -> i32 {
        let conn = http.accept()
        let ws = accept_ws(conn)
        discard http.websocket_close(ws, 1000, "ok")
        return 0
    }
''', 0)
assert websocket_return['errors'] == 0, websocket_return
assert not any('potential resource escape' in message for message in messages(websocket_return)), websocket_return

